#include <string.h>

void handle_request(char *method, char *path) {
    char response[256];
    if (strcmp(path, "/") == 0 || strcmp(path, "/index.html") == 0)
        sprintf(response, "HTTP/1.1 200 OK\r\n\r\n<html><body><h1>Hello</h1></body></html>");
    else
        sprintf(response, "HTTP/1.1 404 Not Found\r\n\r\n<html><body><h1>404 Not Found</h1></body></html>");
